{
  "a_sentences": [
    {
      "a_text": "Le Tribunal fédéral ne s'écarte des faits établis par l'autorité précédente que s'ils ont été constatés de façon manifestement inexacte, c'est-à-dire de manière arbitraire.",
      "b_propositions": ["P1", "P2"]
    },
    {
      "a_text": "Il n'intervient en matière d'appréciation des preuves que si le juge a manifestement mal compris un moyen de preuve, a omis sans raison objective de tenir compte d'une preuve pertinente ou a tiré des déductions insoutenables des éléments recueillis.",
      "b_propositions": ["P2"]
    },
    {
      "a_text": "Il y a novation lorsque le solde du compte a été arrêté et reconnu par les parties, ou par une reconnaissance tacite du solde.",
      "b_propositions": ["P3"]
    },
    {
      "a_text": "L'action de la Banque B.________ est soumise au délai de prescription de dix ans prévu à l'art. 127 CO.",
      "b_propositions": ["P4"]
    },
    {
      "a_text": "La résiliation du contrat de crédit au 10 janvier 2012 a arrêté le compte en cours de période comptable et a ainsi fait partir le délai de prescription.",
      "b_propositions": ["P6"]
    },
    {
      "a_text": "Le grief relatif à la prescription est rejeté.",
      "b_propositions": ["P7"]
    },
    {
      "a_text": "Le grief tiré de la violation de l'art. 8 CC et de la répartition du fardeau de la preuve est irrecevable.",
      "b_propositions": ["P8"]
    },
    {
      "a_text": "Le grief d'abus de droit est rejeté, car le blocage des comptes de la société C.________ SA n'était pas abusif et le recourant n'a pas excipé du bénéfice de discussion réelle.",
      "b_propositions": ["P8"]
    },
    {
      "a_text": "Le grief relatif à la violation des art. 890 et 891 CC est rejeté, faute de violation contractuelle de la part de la Banque B.________ et d'allégation suffisante d'une plainte LP.",
      "b_propositions": ["P8"]
    }
  ]
}
